function APR.party:GetStepDescription(route, stepID)
    if not route or not stepID then return '' end
    local step = APR:GetGroupRouteStep(route, stepID)
    if not step then return '' end

    local stepText = APR:GetStepString(step)
    if step.KillNPC then stepText = APR:GetDungeonKillText(step.KillNPC) end
    local questIDs = {}
    local added = {}

    -- Helper to add a quest ID to the list
    local function AddQuestID(qid)
        if qid and not added[qid] then
            table.insert(questIDs, qid)
            added[qid] = true
        end
    end--[[APR_DIAG]]; AddQuestID = APRTrace("APR-Core/features/group/Party.lua:416:AddQuestID#20", AddQuestID)--[[/APR_DIAG]]

    -- PickUp
    if step.PickUp then
        if type(step.PickUp) == 'table' then
            for _, qid in ipairs(step.PickUp) do AddQuestID(qid) end
        else
            AddQuestID(step.PickUp)
        end
    end

    -- Done
    if step.Done then
        if type(step.Done) == 'table' then
            for _, qid in ipairs(step.Done) do AddQuestID(qid) end
        else
            AddQuestID(step.Done)
        end
    end

    -- Qpart / QpartPart
    local qpartSource = step.Qpart or step.QpartPart
    if qpartSource then
        for qid, _ in pairs(qpartSource) do
            AddQuestID(qid)
        end
    end

    local questNames = {}
    for _, qid in ipairs(questIDs) do
        local name = APR:GetQuestTitle(qid)
        if name then
            table.insert(questNames, "- " .. name)
        end
    end

    if #questNames > 0 then
        stepText = stepText .. "\n" .. table.concat(questNames, "\n")
    end

    return stepText
end--[[APR_DIAG]]; APR.party.GetStepDescription = APRTrace("APR-Core/features/group/Party.lua:405:APR.party:GetStepDescription#19", APR.party.GetStepDescription)--[[/APR_DIAG]]

